-- content-writer: обогащаем setup_schema подсказками (help) и примерами
-- (placeholder) + короткие лейблы. Поля и их required не меняются — только UX
-- визарда настройки, чтобы покупатель давал хороший контекст (особенно EXAMPLES,
-- где раньше было пустое окно без подсказки). Дополняет
-- 2026-05-29_content_writer_approve_schema.sql. Образ ребилдить НЕ нужно.

UPDATE agents
SET setup_schema = '[
    {"key":"TELEGRAM_BOT_TOKEN","label":"Telegram Bot Token","type":"text","required":true,"help":"Создай бота у @BotFather → /newbot и скопируй токен. Обязательно напиши боту /start в личку, иначе он не сможет прислать тебе черновик.","placeholder":"123456789:AAE…"},
    {"key":"CHANNEL_ID","label":"Канал для публикации","type":"text","required":true,"help":"@username канала или числовой -100…. Добавь бота в админы канала с правом публиковать сообщения.","placeholder":"@my_channel"},
    {"key":"OWNER_CHAT_ID","label":"Твой Telegram ID","type":"text","required":true,"help":"Сюда бот шлёт черновики на одобрение. Узнать: напиши @userinfobot команду /start — он вернёт число.","placeholder":"123456789"},
    {"key":"TOPIC","label":"Тема канала","type":"textarea","required":true,"help":"О чём канал, одной фразой — задаёт общий фокус постов.","placeholder":"Практические советы для владельцев кофеен"},
    {"key":"TONE","label":"Тон голоса","type":"textarea","required":true,"help":"Как канал разговаривает с аудиторией.","placeholder":"дружелюбно, по делу, без канцелярита, с лёгким юмором"},
    {"key":"EXAMPLES","label":"Примеры постов","type":"textarea","required":true,"help":"Вставь 2-4 реальных поста как есть, разделяя пустой строкой. Бот копирует манеру, а не темы. Это главный рычаг качества — без примеров тексты выходят усреднёнными.","placeholder":"Сегодня гость спросил, почему у нас нет доставки. Ответил честно: пока возим только по выходным и сами…\n\nМаленький лайфхак для тех, кто только открылся: не гонитесь за меню из 50 позиций. Пять, которые получаются идеально, продают лучше двадцати средних."},
    {"key":"CONTENT_PILLARS","label":"Рубрики","type":"textarea","required":false,"help":"По одной на строку — бот ротирует их по кругу. Пусто = пишет только по теме.","placeholder":"разбор частых ошибок\nполезные инструменты\nкейсы клиентов"},
    {"key":"AUDIENCE","label":"Аудитория","type":"textarea","required":false,"help":"Кто читает канал — бот подстроит подачу.","placeholder":"владельцы небольших кафе и ресторанов"},
    {"key":"FORMAT_RULES","label":"Правила формата","type":"textarea","required":false,"help":"Длина, эмодзи, хэштеги, призывы — любые жёсткие ограничения.","placeholder":"короткие абзацы, без хэштегов, максимум 1 эмодзи"},
    {"key":"AVOID","label":"Чего избегать","type":"textarea","required":false,"help":"Темы и формулировки, которых в канале быть не должно.","placeholder":"политика, обещания дохода, кликбейт"},
    {"key":"POST_INTERVAL_HOURS","label":"Как часто присылать черновик","type":"select","options":["6","12","24","48"],"required":false,"help":"Раз в сколько часов бот готовит новый черновик на одобрение."}
  ]'::jsonb
WHERE slug = 'content-writer';
